<?php declare(strict_types=1); require dirname(__DIR__).'/includes/bootstrap.php'; require ROOT_PATH.'/includes/members.php';$slug=trim((string)($_GET['u']??''));$member=null;if($slug&&($db=database())&&databaseTableExists('wts_members')){$s=$db->prepare('SELECT display_name,profile_slug,bio,created_at FROM wts_members WHERE profile_slug=? AND email_confirmed_at IS NOT NULL LIMIT 1');$s->execute([$slug]);$member=$s->fetch();}$pageTitle=$member?e($member['display_name']).' | Word Truth Spirit':'Profile not found | Word Truth Spirit';require ROOT_PATH.'/includes/header.php';?><main class="member-profile-page"><section class="member-profile-card"><?php if($member):?><span class="member-avatar"><?=e(mb_strtoupper(mb_substr($member['display_name'],0,1)))?></span><p class="kicker">Reader profile</p><h1><?=e($member['display_name'])?></h1><p><?=e($member['bio']?:'A member of the Word Truth Spirit reader community.')?></p><small>Reader since <?=date('F Y',strtotime($member['created_at']))?></small><?php else:?><p class="kicker">Reader profile</p><h1>Profile not found</h1><p>This profile may be private or no longer available.</p><a href="<?=url('blog/')?>">Return to the blog</a><?php endif;?></section></main><?php require ROOT_PATH.'/includes/footer.php'; ?>
